Basic:
import { Tree } from 'vellum-ui'

const treeData = [
  {
    key: 'product',
    title: 'Product',
    children: [
      { key: 'design', title: 'Design' },
      { key: 'dev', title: 'Engineering' },
    ],
  },
  { key: 'marketing', title: 'Marketing' },
]

export function Basic() {
  return <Tree defaultExpandAll defaultSelectedKeys={['design']} options={treeData} />
}

